"""Loads the shared data contract (generated by tools/build_data.py) and exposes lookup tables."""
import json
import pkgutil


def _load(name: str):
    """Reads a JSON file of the data contract from the package (it also works when the world runs from an
    .apworld zip)."""
    return json.loads(pkgutil.get_data(__name__.rpartition(".")[0], "data/" + name).decode("utf-8"))


LOCATIONS: list[dict] = _load("locations.json")
ITEMS: list[dict] = _load("items.json")
REGIONS: dict = _load("regions.json")

GAME_NAME = "Homura-Hime"

ITEM_BY_NAME: dict[str, dict] = {item["name"]: item for item in ITEMS}

# Locations are known by their readable name in Archipelago; the key is the stable internal identifier.
LOCATION_NAME_TO_ID: dict[str, int] = {loc["name"]: loc["id"] for loc in LOCATIONS}
NAME_OF_KEY: dict[str, str] = {loc["key"]: loc["name"] for loc in LOCATIONS}
KEY_OF_NAME: dict[str, str] = {loc["name"]: loc["key"] for loc in LOCATIONS}
ITEM_NAME_TO_ID: dict[str, int] = {item["name"]: item["id"] for item in ITEMS}

# The worlds in story order (the 8 chapters and the climax, which is a world of its own), the finale is separate.
CHAPTERS: list[dict] = [c for c in REGIONS["chapters"] if c["id"] != "LevelFinalP4"]
FINALE: dict = next(c for c in REGIONS["chapters"] if c["id"] == "LevelFinalP4")
CLIMAX_ID = "LevelFinalP0"
# The 8 numbered chapters: what the economy of the logic counts (the climax has no flowers and no clear reward).
NUMBERED_CHAPTERS: list[dict] = [c for c in CHAPTERS if c["id"] != CLIMAX_ID]
# How events and unlock items name a world: "Chapter 3", "Climax".
LABEL_OF: dict[str, str] = {c["id"]: c["label"] for c in CHAPTERS}

# The world (chapter id) each region belongs to; the hub has none.
CHAPTER_OF_REGION: dict[str, str] = {sub["key"]: c["id"] for c in [*CHAPTERS, FINALE] for sub in c["sub_chapters"]}

# Konpeito price and Senbei price of every shop location (the "price" and "senbei" fields of the data contract).
SHOP_PRICES: dict[str, int] = {loc["key"]: loc["price"] for loc in LOCATIONS if loc["category"] == "shop"}
SHOP_SENBEI: dict[str, int] = {loc["key"]: loc["senbei"] for loc in LOCATIONS if loc["category"] == "shop"}

# Every currency item of the pool and its amount. The logic counts them (HomuraHimeWorld.collect): Konpeito and Senbei
# for the shop prices, Sakura Petals for Harumi.
CURRENCY: list[dict] = [i for i in ITEMS if i["type"] == "currency"]
KONPEITO_VALUES: dict[str, int] = {i["name"]: i["amount"] for i in CURRENCY if i["game"] == "Konpeitou"}
SAKURA_VALUES: dict[str, int] = {i["name"]: i["amount"] for i in CURRENCY if i["game"] == "Sakura"}
SENBEI_VALUES: dict[str, int] = {i["name"]: i["amount"] for i in CURRENCY if i["game"] == "Crackers"}
# Sizes a Konpeito filler item can be raised to when the pool has to reach the minimum total (options.MinimumKonpeito).
KONPEITO_LADDER: list[int] = sorted(i["amount"] for i in ITEMS if i.get("ladder"))
# The same with larger pieces on top, for a pool with fewer places (no optional_locations) that cannot reach the total
# otherwise.
KONPEITO_BIG_LADDER: list[int] = sorted(i["amount"] for i in ITEMS if i.get("ladder") or i.get("big_ladder"))

# The sizes of the currency filler as first drawn, with their weights.
SAKURA_ITEMS = ["10 Sakura Petals", "20 Sakura Petals", "30 Sakura Petals", "40 Sakura Petals", "50 Sakura Petals"]
SAKURA_WEIGHTS = [35, 25, 20, 12, 8]
KONPEITO_ITEMS = ["500 Konpeito", "750 Konpeito", "1000 Konpeito", "1500 Konpeito"]
KONPEITO_WEIGHTS = [40, 30, 20, 10]

# Location groups by what they are (usable in plando / hints), the values are location categories.
LOCATION_GROUPS = {
    "Chests": {"chest", "ambush_chest", "head_chase"}, "Senbei": {"senbei"}, "Journals": {"journal"}, "Shop": {"shop"},
    "Encounters": {"encounter"}, "Trials": {"trial"}, "Ambushes": {"ambush_chest", "ambush_reward"},
    "Hand-overs": {"handover", "tournament", "stall"}, "Harumi": {"harumi"},
    "Clear Rewards": {"stage_clear", "soul_core", "tutorial_clear"},
}

# Location categories that are optional content (ambushes, trials = glitched-spirit challenges, Kushinada head chases).
# Encounter locations carry their own "optional" flag, bosses and regular encounters are mandatory.
OPTIONAL_CATEGORIES = {"ambush_chest", "ambush_reward", "trial", "head_chase"}


def is_optional(loc: dict) -> bool:
    """Whether a location is optional content: the ones the options optional_locations and
    optional_location_importance are about."""
    return loc["category"] in OPTIONAL_CATEGORIES or bool(loc.get("optional"))

DASH_SKILLS = ["Skill Phantom Blade", "Skill Spark Rush", "Skill Quake Strike", "Skill Bloodflame Palm"]

# Key items that gate story progress: the quest items an NPC hands over, which open the rest of a chapter.
GATE_ITEMS = {
    "Pretty Little Flower", "Elevator Lever", "Nurikabe's Shoe", "Nurikabe's Hat", "Fresh Fish", "Inugami Certificate",
    "Nurikabe's Gloves",
}
